mkdir -p ~/development/.tmp/stallion-public2 && cat > ~/development/.tmp/stallion-public2/builds.mjs <<'EOF'
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
const env = Object.fromEntries(readFileSync(`${homedir()}/.config/stallion/cf-env`, "utf8").split("\n").map((l) => l.replace(/^export\s+/, "").match(/^([A-Z_]+)=["']?(.*?)["']?$/)).filter(Boolean).map((m) => [m[1], m[2]]));
const acct = "f496802dcadb597e5939f6449c759a43";
const api = (p) => fetch(`https://api.cloudflare.com/client/v4/accounts/${acct}${p}`, { headers: { Authorization: `Bearer ${env.CLOUDFLARE_API_TOKEN}` } }).then(async (r) => ({ status: r.status, body: await r.json() }));
const want = process.argv[2];
const scripts = await api("/workers/scripts");
const script = scripts.body.result?.find((s) => s.id === "stallion");
if (!script) { console.log("scripts", scripts.status, JSON.stringify(scripts.body.errors)); process.exit(1); }
const deadline = Date.now() + 25 * 60_000;
while (Date.now() < deadline) {
  const b = await api(`/builds/workers/${script.tag}/builds?per_page=5`);
  if (b.status !== 200) { console.log("builds", b.status, JSON.stringify(b.body.errors)); process.exit(1); }
  const hit = b.body.result.find((x) => x.build_trigger_metadata?.commit_hash === want);
  if (hit) {
    console.log(hit.build_uuid, hit.status, hit.build_outcome ?? "");
    if (hit.status === "stopped") process.exit(hit.build_outcome === "success" ? 0 : 3);
  } else console.log("no build yet for", want, "latest:", b.body.result.map((x) => `${x.build_trigger_metadata?.commit_hash?.slice(0, 7)}:${x.status}/${x.build_outcome}`).join(" "));
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 30_000);
}
console.log("timeout"); process.exit(4);
EOF
cd ~/development/.tmp/stallion-public2 && timeout 590 node builds.mjs 22f4e30f2dacdad3f1807f4593614339606379f7 2>&1 | tail -4

